CREATE TABLE "MedicineMaster" ("id" TEXT NOT NULL,"code" VARCHAR(50) NOT NULL,"name" VARCHAR(200) NOT NULL,"dosageForm" VARCHAR(100),"strength" VARCHAR(100),"unit" VARCHAR(50) NOT NULL,"groupName" VARCHAR(100),"category" VARCHAR(100),"minStock" INTEGER NOT NULL DEFAULT 0,"maxStock" INTEGER,"active" BOOLEAN NOT NULL DEFAULT true,"uptId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MedicineMaster_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "MedicineMaster_code_key" ON "MedicineMaster"("code"); CREATE INDEX "MedicineMaster_name_idx" ON "MedicineMaster"("name");
CREATE TABLE "MedicineReceipt" ("id" TEXT NOT NULL,"medicineId" TEXT NOT NULL,"uptId" TEXT NOT NULL,"receiptDate" TIMESTAMP(3) NOT NULL,"documentNumber" VARCHAR(100),"source" VARCHAR(200),"batchNumber" VARCHAR(100),"expiryDate" TIMESTAMP(3),"quantity" INTEGER NOT NULL,"unit" VARCHAR(50) NOT NULL,"price" DECIMAL(18,2),"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MedicineReceipt_pkey" PRIMARY KEY ("id"));
CREATE INDEX "MedicineReceipt_uptId_receiptDate_idx" ON "MedicineReceipt"("uptId","receiptDate");
CREATE TABLE "MedicineInbound" ("id" TEXT NOT NULL,"medicineId" TEXT NOT NULL,"uptId" TEXT NOT NULL,"inboundDate" TIMESTAMP(3) NOT NULL,"documentNumber" VARCHAR(100),"batchNumber" VARCHAR(100),"expiryDate" TIMESTAMP(3),"quantity" INTEGER NOT NULL,"unit" VARCHAR(50) NOT NULL,"source" VARCHAR(200),"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MedicineInbound_pkey" PRIMARY KEY ("id"));
CREATE INDEX "MedicineInbound_uptId_inboundDate_idx" ON "MedicineInbound"("uptId","inboundDate");
CREATE TABLE "MedicineDistribution" ("id" TEXT NOT NULL,"medicineId" TEXT NOT NULL,"sourceUptId" TEXT NOT NULL,"destinationUptId" TEXT NOT NULL,"distributionDate" TIMESTAMP(3) NOT NULL,"documentNumber" VARCHAR(100),"batchNumber" VARCHAR(100),"quantity" INTEGER NOT NULL,"unit" VARCHAR(50) NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MedicineDistribution_pkey" PRIMARY KEY ("id"));
CREATE INDEX "MedicineDistribution_sourceUptId_distributionDate_idx" ON "MedicineDistribution"("sourceUptId","distributionDate"); CREATE INDEX "MedicineDistribution_destinationUptId_distributionDate_idx" ON "MedicineDistribution"("destinationUptId","distributionDate");
CREATE TABLE "MedicineIssue" ("id" TEXT NOT NULL,"medicineId" TEXT NOT NULL,"uptId" TEXT NOT NULL,"issueDate" TIMESTAMP(3) NOT NULL,"batchNumber" VARCHAR(100),"quantity" INTEGER NOT NULL,"unit" VARCHAR(50) NOT NULL,"purpose" VARCHAR(200),"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MedicineIssue_pkey" PRIMARY KEY ("id"));
CREATE INDEX "MedicineIssue_uptId_issueDate_idx" ON "MedicineIssue"("uptId","issueDate");
CREATE TABLE "MedicineStockOpening" ("id" TEXT NOT NULL,"medicineId" TEXT NOT NULL,"uptId" TEXT NOT NULL,"asOfDate" TIMESTAMP(3) NOT NULL,"quantity" INTEGER NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MedicineStockOpening_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "MedicineStockOpening_medicineId_uptId_asOfDate_key" ON "MedicineStockOpening"("medicineId","uptId","asOfDate"); CREATE INDEX "MedicineStockOpening_uptId_asOfDate_idx" ON "MedicineStockOpening"("uptId","asOfDate");
